public interface UserRepository extends ReactiveCrudRepository<UserEntity, UUID> {
    Mono<UserEntity> findByEmail(String email);   // requête dérivée du nom
}

// Domaine (aucune dépendance technique)
public record User(UserId id, String email, String displayName) {}

// Adaptateur out : entité + mapping vers le domaine
record UserEntity(UUID id, String email, String displayName) {
    User toDomain() { return new User(new UserId(id), email, displayName); }
}

record RoadmapEntity(@Id UUID id, String title,
                     @Version long version) {}

// À l'UPDATE, Spring Data ajoute AND version = :ancienneVersion
// et incrémente version. Si 0 ligne touchée -> OptimisticLockingFailureException
// => quelqu'un a écrit entre-temps, on rejoue (voir nœud Transactions).
